mapper.update:
UPDATE PsychologyVR.BIO_CHECK
SET standby_yn=4
WHERE vital_device_number=#{vital_divice_number} AND standby_yn IN (0,1) ;

UPDATE PsychologyVR.BIO_CHECK
SET standby_yn=1
WHERE vital_device_number=#{vital_divice_number} AND standby_yn=0 ;

UPDATE PsychologyVR.BIO_CHECK
SET standby_yn=2
WHERE vital_device_number=#{vital_divice_number} AND standby_yn=1 ;
